sp_widget.client_script:
function($scope, $location, spUtil) {
	var c = this;


		 $scope.selectedIds = [];
	c.selectRecord = function(val, sys_id) {

		if(val) {

			$scope.selectedIds.push(sys_id);
		}
		else {
			$scope.selectedIds.pop(sys_id);
		}
					alert('IDs: ' + $scope.selectedIds.toString());

	}

	c.groupAsmt = function() {
		var idObj = {sys_ids: $scope.selectedIds.toString()};
				c.server.get(idObj).then(function(resp) {
			alert(resp.data.groupRtn.msgs.info + '  :   ' + resp.data.groupRtn.msgs.error);
							alert('here');
		})

	}
}

sp_widget.css:
.alert {
    margin-top: 20px;
}

.b {
    margin-top: 15px;
}

.panel-heading {
		padding: 10px 0 5px 40px;
}

.panel-body {
    padding: 40px;
}

.panel-body {
    padding: 15px;
    padding-bottom: 40px;
}

.label.upper-case {
 	text-transform: uppercase; 
}

.cell {
  	display: flex;
	align-items: center;
  	height: 70px;
  	padding: 0;
	overflow: hidden;
	word-break: break-word;
}

.row-border {
	border-bottom: 1px solid #dee5e7;
}

.th .cell {
	 	padding-bottom: 10px;
    align-items: flex-end; 
  	height: 60px;
}

.header .cell {
	font-weight: 700;
}

.contact-row:hover .cell {
  	background-color: $list-group-hover-bg;
}

.cell.flex-right {
 		justify-content: flex-end; 
		padding-right: 0rem;
}

.first-cell {
	  padding-left: 10px;
}

a#new_contact:hover, 
a#new_contact:hover i,
.panel.vdp .contact-row a:hover{
    color: $brand-primary;
}

.contact-row .label.upper-case {
	  padding: .3em .6em .2em;
  	margin-left: 4px;
}

.contact-row:hover > div {
    background-color: $breadcrumb-bg!important;
}

.label-primary,
.label-warning {
  min-width: 75px;
}

.label-primary {
    color: $label-color;
  	background-color: $brand-success
}

.label-warning {
    background-color: $label-warning-bg;
  	color: $label-color;
}

.panel-body .contact-row {
  .no-gutter > [class*='col-'] {
    padding-right:0;
    padding-left:0;
  }
}

@media (max-width: 767px){
  .cell {
	height: 50px;
    border-bottom: 1px solid #dee5e7;
  }
}

sp_widget.script:
(function() {
    var type = options.type || 'attestation'; //attestation, risk, tiering
    var utils = new x_631631_sc_grc_co.grcAssessmentUtilBase();
    var list = utils.getAssessments(type);

    data.list = list;

    var text = {};

    if (type == 'attestation')
        text = {
            'no_result': gs.getMessage('You have no attestations.'),
            'your_list': gs.getMessage('My Attestations'),
            'column_label': gs.getMessage('Attestation'),
            'button_label': gs.getMessage('Take Attestation')
        }
    else if (type == 'risk')
        text = {
            'no_result': gs.getMessage('You have no risk assessments.'),
            'your_list': gs.getMessage('My Assessments'),
            'column_label': gs.getMessage('Assessment'),
            'button_label': gs.getMessage('Take Assessment')
        }
    else if (type == 'tiering')
        text = {
            'no_result': gs.getMessage('You have no tiering assessments.'),
            'your_list': gs.getMessage('My Assessments'),
            'column_label': gs.getMessage('Assessment'),
            'button_label': gs.getMessage('Take Assessment')
        }
    else if (type == 'privacy')
        text = {
            'no_result': gs.getMessage('You have no privacy assessments.'),
            'your_list': gs.getMessage('My Assessments'),
            'column_label': gs.getMessage('Assessment'),
            'button_label': gs.getMessage('Take Assessment')
        }

    data.text = text;

		if(input) {
			gs.info('input: ' + input.sys_ids);
			data.groupRtn = recHandler(input.sys_ids);

		}

	function recHandler(sys_ids) {
		gs.info('sys_ids: ' + sys_ids)
		var groupAsmt = new sn_grc.GRCAssessmentUtils().createGroup(sys_ids, 'grouped', 'sn_grc_profile');
		gs.info(groupAsmt.msgs.info  + ' - ' + groupAsmt.msgs.error);
		return groupAsmt;
	}
})();
